#!/usr/bin/env python3
"""Offline BGP relationship inference and route-leak scoring service.

Protocol version 1, revision 1.  One JSON request on stdin, one JSON
response on stdout.  Pure standard library, no I/O besides stdin/stdout.

Pipeline
--------
1.  Strict schema/bound validation of the whole request.
2.  Path normalization (IXP removal, prepend collapsing, loop rejection,
    directed aggregation by summed counts).
3.  Simultaneous topology peeling of peripheral links, recording rounds.
4.  Exact joint inference over the core links using the specified ternary
    potential  phi_e(X) = sum of observation counts whose centre variable
    equals g(L,R),  evaluated with bucket elimination along the supplied
    elimination order (width <= 4) plus a junction-tree upward/downward
    pass for exact marginals.
5.  Declaration-aware query scoring with exact rational arithmetic.
"""

import json
import os
import re
import sys
from fractions import Fraction
from itertools import product as _cartesian


class Invalid(Exception):
    """Schema, bound or structural violation of the request."""


# ------------------------------------------------------------------ limits
MAX_INPUT_BYTES = 4194304
ASN_MAX = 4294967295
MAX_RIB_RECORDS = 2000
MAX_PRIOR_RECORDS = 2000
MAX_DECLARED_RECORDS = 2000
MAX_QUERY_RECORDS = 512
MAX_IXPS = 1024
MAX_PATH_LEN = 64
MAX_RIB_LENGTH_SUM = 40000
MAX_RIB_LINKS = 4096
MAX_CORE_LINKS = 64
MAX_COUNT = 1000000
MAX_WEIGHT = 1000000
MAX_THRESHOLD = 1000000
MAX_NEIGHBORS = 4

UNIFORM = (Fraction(1, 3), Fraction(1, 3), Fraction(1, 3))
REL_CODE = {'c2p': 0, 'p2p': 1, 'p2c': 2}
# rows: left context type, columns: right context type (0=c2p,1=p2p,2=p2c)
G_TABLE = ((0, 0, 1), (1, 1, 2), (1, 1, 2))
REVERSE = (2, 1, 0)
TOP_KEYS = frozenset(('version', 'ixps', 'rib', 'priors', 'declared',
                      'order', 'queries'))
ID_RE = re.compile(r'[A-Za-z0-9_.-]{1,64}')

IDENTITY = ((), [1])


# ------------------------------------------------------------- json input
def _pairs(pairs):
    out = {}
    for key, value in pairs:
        if key in out:
            raise Invalid('duplicate object key')
        out[key] = value
    return out


def _bad_float(_):
    raise Invalid('non integer number')


def _bad_const(_):
    raise Invalid('non integer number')


def _load(raw):
    if len(raw) > MAX_INPUT_BYTES:
        raise Invalid('input exceeds byte bound')
    try:
        text = raw.decode('utf-8')
    except (UnicodeDecodeError, ValueError):
        raise Invalid('malformed utf-8')
    try:
        return json.loads(text, object_pairs_hook=_pairs,
                          parse_float=_bad_float, parse_constant=_bad_const)
    except Invalid:
        raise
    except Exception:
        raise Invalid('malformed json')


# ------------------------------------------------------------- validators
def _need_int(value):
    if isinstance(value, bool) or not isinstance(value, int):
        raise Invalid('expected an integer')
    return value


def _need_asn(value):
    _need_int(value)
    if value < 1 or value > ASN_MAX:
        raise Invalid('asn out of range')
    return value


def _need_list(value):
    if not isinstance(value, list):
        raise Invalid('expected an array')
    return value


def _need_fields(rec, names):
    if not isinstance(rec, dict) or set(rec.keys()) != names:
        raise Invalid('unexpected record fields')
    return rec


def _canon(a, b):
    return (a, b) if a < b else (b, a)


def _parse(doc):
    if not isinstance(doc, dict):
        raise Invalid('top level must be an object')
    if set(doc.keys()) != TOP_KEYS:
        raise Invalid('unexpected top level keys')
    version = doc['version']
    if isinstance(version, bool) or not isinstance(version, int) or version != 1:
        raise Invalid('unsupported version')

    ixps = set()
    for value in _need_list(doc['ixps']):
        _need_asn(value)
        if value in ixps:
            raise Invalid('duplicate ixp')
        ixps.add(value)
    if len(ixps) > MAX_IXPS:
        raise Invalid('too many ixps')

    rib = []
    total_len = 0
    records = _need_list(doc['rib'])
    if len(records) > MAX_RIB_RECORDS:
        raise Invalid('too many rib records')
    for rec in records:
        _need_fields(rec, frozenset(('path', 'count')))
        path = _need_list(rec['path'])
        if len(path) > MAX_PATH_LEN:
            raise Invalid('rib path too long')
        p = tuple(_need_asn(x) for x in path)
        count = rec['count']
        _need_int(count)
        if count < 1 or count > MAX_COUNT:
            raise Invalid('count out of range')
        total_len += len(p)
        if total_len > MAX_RIB_LENGTH_SUM:
            raise Invalid('rib path length sum exceeded')
        rib.append((p, count))

    priors = {}
    records = _need_list(doc['priors'])
    if len(records) > MAX_PRIOR_RECORDS:
        raise Invalid('too many priors')
    for rec in records:
        _need_fields(rec, frozenset(('link', 'weights')))
        link = _need_list(rec['link'])
        if len(link) != 2:
            raise Invalid('prior link arity')
        u = _need_asn(link[0])
        v = _need_asn(link[1])
        if u == v:
            raise Invalid('prior self link')
        weights = _need_list(rec['weights'])
        if len(weights) != 3:
            raise Invalid('prior weight arity')
        ws = []
        for x in weights:
            _need_int(x)
            if x < 0 or x > MAX_WEIGHT:
                raise Invalid('weight out of range')
            ws.append(x)
        total = ws[0] + ws[1] + ws[2]
        if total <= 0:
            raise Invalid('prior weight sum must be positive')
        vec = (Fraction(ws[0], total), Fraction(ws[1], total),
               Fraction(ws[2], total))
        if u > v:
            vec = (vec[2], vec[1], vec[0])
        key = (u, v) if u < v else (v, u)
        if key in priors:
            raise Invalid('duplicate prior pair')
        priors[key] = vec

    declared = {}
    records = _need_list(doc['declared'])
    if len(records) > MAX_DECLARED_RECORDS:
        raise Invalid('too many declarations')
    for rec in records:
        _need_fields(rec, frozenset(('link', 'rel')))
        link = _need_list(rec['link'])
        if len(link) != 2:
            raise Invalid('declared link arity')
        u = _need_asn(link[0])
        v = _need_asn(link[1])
        if u == v:
            raise Invalid('declared self link')
        rel = rec['rel']
        if not isinstance(rel, str) or rel not in REL_CODE:
            raise Invalid('unknown relation')
        onehot = [0, 0, 0]
        onehot[REL_CODE[rel]] = 1
        onehot = (onehot[0], onehot[1], onehot[2])
        if u > v:
            onehot = (onehot[2], onehot[1], onehot[0])
        key = (u, v) if u < v else (v, u)
        if key in declared:
            raise Invalid('duplicate declared pair')
        declared[key] = onehot

    order = []
    seen = set()
    for rec in _need_list(doc['order']):
        if not isinstance(rec, list) or len(rec) != 2:
            raise Invalid('order entry arity')
        u = _need_asn(rec[0])
        v = _need_asn(rec[1])
        if u >= v:
            raise Invalid('order entry must be canonical')
        if (u, v) in seen:
            raise Invalid('duplicate order entry')
        seen.add((u, v))
        order.append((u, v))

    queries = []
    ids = set()
    records = _need_list(doc['queries'])
    if len(records) > MAX_QUERY_RECORDS:
        raise Invalid('too many queries')
    for rec in records:
        _need_fields(rec, frozenset(('id', 'path', 'threshold')))
        qid = rec['id']
        if not isinstance(qid, str) or not ID_RE.fullmatch(qid):
            raise Invalid('query id')
        if qid in ids:
            raise Invalid('duplicate query id')
        ids.add(qid)
        path = _need_list(rec['path'])
        if len(path) > MAX_PATH_LEN:
            raise Invalid('query path too long')
        p = tuple(_need_asn(x) for x in path)
        thr = _need_list(rec['threshold'])
        if len(thr) != 2:
            raise Invalid('threshold arity')
        a = _need_int(thr[0])
        b = _need_int(thr[1])
        if b < 1 or b > MAX_THRESHOLD or a < 0 or a > b:
            raise Invalid('threshold out of range')
        queries.append((qid, p, a, b))

    return ixps, rib, priors, declared, order, queries


# ------------------------------------------------------------- path tools
def _normalize(path, ixps):
    out = []
    for asn in path:
        if asn in ixps:
            continue
        if out and out[-1] == asn:
            continue
        out.append(asn)
    return out


# ----------------------------------------------------- simultaneous peeling
def _peel(paths):
    """Peel peripheral links simultaneously.

    Returns (all_links, rounds, surviving path records).
    """
    info = {}
    cand = set()
    all_links = set()

    def refresh(link):
        st = info[link]
        if st[0] > 0 and (st[1] == 0 or st[2] == 0):
            cand.add(link)
        else:
            cand.discard(link)

    def add(path, sign):
        first = path[0]
        last = path[-1]
        for i in range(len(path) - 1):
            link = _canon(path[i], path[i + 1])
            st = info.get(link)
            if st is None:
                st = info[link] = [0, 0, 0]
            st[0] += sign
            if path[i] != first and path[i] != last:
                st[1] += sign
            if path[i + 1] != first and path[i + 1] != last:
                st[2] += sign
            refresh(link)

    for path, _count in paths:
        for i in range(len(path) - 1):
            all_links.add(_canon(path[i], path[i + 1]))
        add(path, 1)

    current = list(paths)
    rounds = {}
    round_no = 0
    while cand:
        marked = set(cand)
        round_no += 1
        for link in marked:
            rounds[link] = round_no
        trims = []
        keep = []
        for rec in current:
            path = rec[0]
            if _canon(path[0], path[1]) in marked or \
                    _canon(path[-2], path[-1]) in marked:
                trims.append(rec)
            else:
                keep.append(rec)
        survivors = keep
        for path, count in trims:
            n = len(path)
            drop_first = _canon(path[0], path[1]) in marked
            drop_last = _canon(path[-2], path[-1]) in marked
            start = 1 if drop_first else 0
            end = n - 1 if drop_last else n
            if end - start < 2:
                add(path, -1)
                continue
            trimmed = path[start:end]
            if drop_first:
                link = _canon(path[0], path[1])
                st = info[link]
                st[0] -= 1
                if n > 2:
                    if link[0] == path[1]:
                        st[1] -= 1
                    else:
                        st[2] -= 1
                refresh(link)
                link = _canon(trimmed[0], trimmed[1])
                st = info[link]
                if link[0] == trimmed[0]:
                    st[1] -= 1
                else:
                    st[2] -= 1
                refresh(link)
            if drop_last:
                if not (drop_first and n == 2):
                    link = _canon(path[-2], path[-1])
                    st = info[link]
                    st[0] -= 1
                    if n > 2:
                        if link[0] == path[-2]:
                            st[1] -= 1
                        else:
                            st[2] -= 1
                    refresh(link)
                link = _canon(trimmed[-2], trimmed[-1])
                st = info[link]
                if link[0] == trimmed[-1]:
                    st[1] -= 1
                else:
                    st[2] -= 1
                refresh(link)
            survivors.append((trimmed, count))
        current = survivors
    return all_links, rounds, current


# ---------------------------------------------------------------- factors
# A factor is (scope, values); scope is an ascending tuple of variable
# indices and values is a flat list with the first scope variable as the
# most significant ternary digit.

def _fmul(f, g):
    fs, fv = f
    gs, gv = g
    if fs == gs:
        return (fs, [a * b for a, b in zip(fv, gv)])
    scope = tuple(sorted(set(fs) | set(gs)))
    n = len(scope)
    fstride = [0] * n
    gstride = [0] * n
    flen = len(fs)
    glen = len(gs)
    fpos = {v: flen - 1 - i for i, v in enumerate(fs)}
    gpos = {v: glen - 1 - i for i, v in enumerate(gs)}
    for k, v in enumerate(scope):
        if v in fpos:
            fstride[k] = 3 ** fpos[v]
        if v in gpos:
            gstride[k] = 3 ** gpos[v]
    total = 3 ** n
    fmap = [0] * total
    gmap = [0] * total
    idx = 0
    for digits in _cartesian(range(3), repeat=n):
        x = 0
        y = 0
        for k in range(n):
            d = digits[k]
            x += d * fstride[k]
            y += d * gstride[k]
        fmap[idx] = x
        gmap[idx] = y
        idx += 1
    out = [fv[fmap[j]] * gv[gmap[j]] for j in range(total)]
    return (scope, out)


def _fsumout(f, var):
    scope, vals = f
    p = scope.index(var)
    n = len(scope)
    if n == 1:
        return ((), [sum(vals)])
    stride = 3 ** (n - 1 - p)
    block = stride * 3
    hin = 3 ** (n - 1 - p)
    out = [0] * (hin * stride)
    for h in range(hin):
        base = h * block
        target = h * stride
        for d in range(3):
            src = base + d * stride
            for lo in range(stride):
                out[target + lo] += vals[src + lo]
    return (scope[:p] + scope[p + 1:], out)


def _fkeep(f, var):
    """Sum out every variable except var."""
    scope, vals = f
    p = scope.index(var)
    n = len(scope)
    stride = 3 ** (n - 1 - p)
    block = stride * 3
    hin = 3 ** (n - 1 - p)
    out = [0, 0, 0]
    for h in range(hin):
        base = h * block
        for d in range(3):
            src = base + d * stride
            acc = 0
            for lo in range(stride):
                acc += vals[src + lo]
            out[d] += acc
    return ((var,), out)


def _project(f, keep):
    keepset = set(keep)
    drop = [v for v in f[0] if v not in keepset]
    for v in drop:
        f = _fsumout(f, v)
    return f


# ------------------------------------------------------- core model build
def _occurrences(final_paths, var_index, m):
    """Group occurrences of every core link by their context signature."""
    occ = [{} for _ in range(m)]
    for path, count in final_paths:
        n = len(path)
        rev = path[::-1]
        for seq in (path, rev):
            for j in range(n - 1):
                if seq[j] >= seq[j + 1]:
                    continue
                ev = var_index[(seq[j], seq[j + 1])]
                if j == 0:
                    lk = (0, -1)
                else:
                    x = seq[j - 1]
                    y = seq[j]
                    cv = var_index[_canon(x, y)]
                    lk = (1, cv) if x < y else (2, cv)
                if j + 2 >= n:
                    rk = (3, -1)
                else:
                    x = seq[j + 1]
                    y = seq[j + 2]
                    cv = var_index[_canon(x, y)]
                    rk = (1, cv) if x < y else (2, cv)
                key = (lk, rk)
                bucket = occ[ev]
                bucket[key] = bucket.get(key, 0) + count
    return occ


def _context_value(kind, amap):
    code, var = kind
    if code == 0:
        return 0
    if code == 3:
        return 2
    value = amap[var]
    return value if code == 1 else REVERSE[value]


def _scopes(occ):
    out = []
    for groups in occ:
        ctx = set()
        for (lk, rk) in groups:
            if lk[0] in (1, 2):
                ctx.add(lk[1])
            if rk[0] in (1, 2):
                ctx.add(rk[1])
        out.append(tuple(sorted([e for e in range(len(occ)) if e == len(occ)]
                                + [0] * 0)) if False else None)
    return out


def _build_scopes(occ, m):
    out = []
    for e in range(m):
        ctx = set()
        for (lk, rk) in occ[e]:
            if lk[0] in (1, 2):
                ctx.add(lk[1])
            if rk[0] in (1, 2):
                ctx.add(rk[1])
        out.append(tuple(sorted(ctx + (e,) if isinstance(ctx, tuple) else
                                 tuple(sorted(ctx)) + (e,))))
    return out


def _check_width(scopes, order_vars, m):
    adj = [set() for _ in range(m)]
    for scope in scopes:
        k = len(scope)
        for i in range(k):
            si = adj[scope[i]]
            for j in range(i + 1, k):
                sj = scope[j]
                si.add(sj)
                adj[sj].add(scope[i])
    done = set()
    for v in order_vars:
        nbrs = adj[v] - done
        if len(nbrs) > MAX_NEIGHBORS:
            raise Invalid('elimination order exceeds width 4')
        nl = list(nbrs)
        for i in range(len(nl)):
            ai = adj[nl[i]]
            for j in range(i + 1, len(nl)):
                ai.add(nl[j])
                adj[nl[j]].add(nl[i])
        done.add(v)


def _tables(occ, scopes, m):
    factors = []
    for e in range(m):
        scope = scopes[e]
        n = len(scope)
        epos = scope.index(e)
        size = 3 ** n
        table = [0] * size
        groups = list(occ[e].items())
        digits = [0] * n
        for idx in range(size):
            x = idx
            for k in range(n - 1, -1, -1):
                digits[k] = x % 3
                x //= 3
            amap = {}
            for k in range(n):
                amap[scope[k]] = digits[k]
            centre = digits[epos]
            acc = 0
            for (lk, rk), count in groups:
                left = _context_value(lk, amap)
                right = _context_value(rk, amap)
                if centre == G_TABLE[left][right]:
                    acc += count
            table[idx] = acc
        factors.append((scope, table))
    return factors


# --------------------------------------------------------- joint inference
def _eliminate(factors, order_vars):
    """Bucket elimination along order_vars with an exact downward pass."""
    m = len(order_vars)
    pos = [0] * m
    for i, v in enumerate(order_vars):
        pos[v] = i
    orig = [[] for _ in range(m)]
    recv = [[] for _ in range(m)]
    for f in factors:
        best = m
        bucket = -1
        for v in f[0]:
            p = pos[v]
            if p < best:
                best = p
                bucket = v
        orig[best].append(f)

    psi = [None] * m
    local = [None] * m
    parent = [-1] * m
    upmsg = [None] * m
    z = 1
    for i in range(m):
        cur = IDENTITY
        for f in orig[i]:
            cur = f if cur is IDENTITY else _fmul(cur, f)
        local[i] = cur
        for msg in recv[i]:
            cur = msg if cur is IDENTITY else _fmul(cur, msg)
        psi[i] = cur
        lam = _fsumout(cur, order_vars[i])
        if not lam[0]:
            z *= lam[1][0]
        else:
            best = m
            target = -1
            for v in lam[0]:
                p = pos[v]
                if p < best:
                    best = p
                    target = v
            parent[i] = best
            recv[best].append(lam)
            upmsg[i] = lam

    children = [[] for _ in range(m)]
    for i in range(m):
        if parent[i] >= 0:
            children[parent[i]].append(i)

    downmsg = [None] * m
    marg = [None] * m
    for i in range(m - 1, -1, -1):
        belief = psi[i]
        if parent[i] >= 0:
            belief = _fmul(belief, downmsg[i])
        marg[i] = _fkeep(belief, order_vars[i])[1]
        kids = children[i]
        if kids:
            base = local[i]
            if parent[i] >= 0:
                base = _fmul(base, downmsg[i])
            k = len(kids)
            msgs = [upmsg[c] for c in kids]
            prefix = [base]
            for msg in msgs:
                prefix.append(_fmul(prefix[-1], msg))
            suffix = [None] * (k + 1)
            acc = None
            for j in range(k - 1, -1, -1):
                acc = msgs[j] if acc is None else _fmul(msgs[j], acc)
                suffix[j] = acc
            for j, c in enumerate(kids):
                right = suffix[j + 1] if j + 1 <= k - 1 else None
                without = prefix[j] if right is None else _fmul(prefix[j], right)
                sep = tuple(v for v in psi[c][0] if v != order_vars[c])
                downmsg[c] = _project(without, sep)
    return z, marg


# ------------------------------------------------------------------- main
def _process(doc):
    ixps, rib, priors, declared, order, queries = _parse(doc)

    aggregated = {}
    for path, count in rib:
        norm = _normalize(path, ixps)
        if len(norm) < 2 or len(set(norm)) != len(norm):
            continue
        key = tuple(norm)
        aggregated[key] = aggregated.get(key, 0) + count
    paths = list(aggregated.items())

    all_links, rounds, surviving = _peel(paths)
    if len(all_links) > MAX_RIB_LINKS:
        raise Invalid('too many distinct rib links')

    core = set()
    for path, _count in surviving:
        for i in range(len(path) - 1):
            core.add(_canon(path[i], path[i + 1]))
    if len(core) > MAX_CORE_LINKS:
        raise Invalid('too many core links')

    if len(order) != len(core) or set(order) != core:
        raise Invalid('order is not a permutation of the core links')

    core_list = sorted(core)
    m = len(core_list)
    var_index = {e: i for i, e in enumerate(core_list)}

    final_agg = {}
    for path, count in surviving:
        final_agg[path] = final_agg.get(path, 0) + count
    final_paths = list(final_agg.items())

    if m:
        occ = _occurrences(final_paths, var_index, m)
        scopes = []
        for e in range(m):
            ctx = set()
            for (lk, rk) in occ[e]:
                if lk[0] in (1, 2):
                    ctx.add(lk[1])
                if rk[0] in (1, 2):
                    ctx.add(rk[1])
            scopes.append(tuple(sorted(ctx | {e})))
        order_vars = [var_index[e] for e in order]
        _check_width(scopes, order_vars, m)
        factors = _tables(occ, scopes, m)
        z, marg = _eliminate(factors, order_vars)
        if z == 0:
            return {'error': 'zero-partition'}
        marg_by_var = [None] * m
        for i, v in enumerate(order_vars):
            marg_by_var[v] = marg[i]
        core_prob = {}
        for e in core_list:
            vec = marg_by_var[var_index[e]]
            total = vec[0] + vec[1] + vec[2]
            core_prob[e] = (Fraction(vec[0], total), Fraction(vec[1], total),
                            Fraction(vec[2], total))
    else:
        core_prob = {}

    links_out = []
    for e in sorted(all_links):
        if e in core:
            vec = marg_by_var[var_index[e]]
            total = vec[0] + vec[1] + vec[2]
            prob = [float(Fraction(x, total)) for x in vec]
            links_out.append({'link': [e[0], e[1]], 'round': 0, 'prob': prob})
        else:
            vec = priors.get(e, UNIFORM)
            links_out.append({'link': [e[0], e[1]], 'round': rounds[e],
                              'prob': [float(x) for x in vec]})

    threshold_cache = {}
    queries_out = []
    for qid, raw_path, ta, tb in queries:
        norm = _normalize(raw_path, ixps)
        looped = len(set(norm)) != len(norm)
        if looped:
            queries_out.append({'id': qid, 'path': list(norm),
                                'status': 'loop', 'score': None, 'full': None,
                                'witness': None, 'leaked': None})
            continue
        vectors = []
        for i in range(len(norm) - 1):
            u = norm[i]
            v = norm[i + 1]
            key = (u, v) if u < v else (v, u)
            if key in declared:
                base = declared[key]
            elif key in core_prob:
                base = core_prob[key]
            elif key in priors:
                base = priors[key]
            else:
                base = UNIFORM
            if u < v:
                vectors.append(base)
            else:
                vectors.append((base[2], base[1], base[0]))
        if len(vectors) < 2:
            score = Fraction(1)
            witness = None
            full = 1.0
        else:
            triples = []
            prev = vectors[0]
            for cur in vectors[1:]:
                up = prev[0]
                dn = cur[2]
                triples.append(up + dn - up * dn)
                prev = cur
            best = min(triples)
            witness = triples.index(best)
            score = best
            up = 1.0
            peer = 0.0
            down = 0.0
            for vec in vectors:
                a = float(vec[0])
                b = float(vec[1])
                c = float(vec[2])
                up, peer, down = up * a, up * b, (up + peer + down) * c
            full = up + peer + down
        key = (ta, tb)
        limit = threshold_cache.get(key)
        if limit is None:
            limit = threshold_cache[key] = Fraction(ta, tb)
        leaked = score < limit
        queries_out.append({'id': qid, 'path': list(norm), 'status': 'ok',
                            'score': float(score), 'full': float(full),
                            'witness': witness, 'leaked': leaked})
    return {'version': 1, 'links': links_out, 'queries': queries_out}


def main():
    debug = bool(os.environ.get('BGP_DEBUG'))
    try:
        raw = sys.stdin.buffer.read()
        doc = _load(raw)
        result = _process(doc)
    except Invalid:
        result = {'error': 'invalid'}
    except Exception:
        if debug:
            raise
        result = {'error': 'invalid'}
    sys.stdout.write(json.dumps(result, allow_nan=False))
    sys.stdout.write('\n')


if __name__ == '__main__':
    main()
